package monitoring

import (
	"fmt"
	"sync"
	"time"
)

// MetricType represents the type of metric
type MetricType string

const (
	MetricThroughput  MetricType = "throughput"
	MetricLatency     MetricType = "latency"
	MetricMemory      MetricType = "memory"
	MetricCPU         MetricType = "cpu"
	MetricCacheHit    MetricType = "cache_hit_rate"
	MetricErrorRate   MetricType = "error_rate"
)

// Metric represents a single metric measurement
type Metric struct {
	Name        string
	Type        MetricType
	Value       float64
	Unit        string
	Timestamp   time.Time
	Tags        map[string]string
	Labels      map[string]string
}

// LatencyMetrics stores latency percentiles
type LatencyMetrics struct {
	P50 float64
	P95 float64
	P99 float64
	Max float64
}

// MetricsCollector manages metric collection with minimal overhead
type MetricsCollector struct {
	mu              sync.RWMutex
	metrics         map[string][]Metric
	aggregates      map[string]interface{}
	startTime       time.Time
	sampleInterval  time.Duration
	maxStoredSamples int
}

// NewMetricsCollector creates a new metrics collector
func NewMetricsCollector(sampleInterval time.Duration, maxSamples int) *MetricsCollector {
	return &MetricsCollector{
		metrics:          make(map[string][]Metric),
		aggregates:       make(map[string]interface{}),
		startTime:        time.Now(),
		sampleInterval:   sampleInterval,
		maxStoredSamples: maxSamples,
	}
}

// Record records a single metric
func (mc *MetricsCollector) Record(metric Metric) {
	mc.mu.Lock()
	defer mc.mu.Unlock()

	metric.Timestamp = time.Now()
	key := metric.Name

	if _, exists := mc.metrics[key]; !exists {
		mc.metrics[key] = make([]Metric, 0)
	}

	mc.metrics[key] = append(mc.metrics[key], metric)

	// Keep only maxStoredSamples to control memory usage
	if len(mc.metrics[key]) > mc.maxStoredSamples {
		mc.metrics[key] = mc.metrics[key][1:]
	}
}

// RecordThroughput records operations per second
func (mc *MetricsCollector) RecordThroughput(name string, opsPerSec float64, tags map[string]string) {
	mc.Record(Metric{
		Name:   name,
		Type:   MetricThroughput,
		Value:  opsPerSec,
		Unit:   "ops/sec",
		Tags:   tags,
		Labels: make(map[string]string),
	})
}

// RecordLatency records latency metrics
func (mc *MetricsCollector) RecordLatency(name string, latency LatencyMetrics, tags map[string]string) {
	mc.mu.Lock()
	defer mc.mu.Unlock()

	key := fmt.Sprintf("%s_latency", name)
	mc.aggregates[key] = latency
}

// RecordMemory records memory usage
func (mc *MetricsCollector) RecordMemory(name string, peakMB float64, tags map[string]string) {
	mc.Record(Metric{
		Name:   name,
		Type:   MetricMemory,
		Value:  peakMB,
		Unit:   "MB",
		Tags:   tags,
		Labels: make(map[string]string),
	})
}

// RecordCPU records CPU usage percentage
func (mc *MetricsCollector) RecordCPU(name string, usagePercent float64, tags map[string]string) {
	mc.Record(Metric{
		Name:   name,
		Type:   MetricCPU,
		Value:  usagePercent,
		Unit:   "%",
		Tags:   tags,
		Labels: make(map[string]string),
	})
}

// RecordCacheHitRate records cache hit rate
func (mc *MetricsCollector) RecordCacheHitRate(name string, hitRate float64, tags map[string]string) {
	mc.Record(Metric{
		Name:   name,
		Type:   MetricCacheHit,
		Value:  hitRate * 100, // Convert to percentage
		Unit:   "%",
		Tags:   tags,
		Labels: make(map[string]string),
	})
}

// RecordErrorRate records error rate
func (mc *MetricsCollector) RecordErrorRate(name string, errorRate float64, tags map[string]string) {
	mc.Record(Metric{
		Name:   name,
		Type:   MetricErrorRate,
		Value:  errorRate * 100, // Convert to percentage
		Unit:   "%",
		Tags:   tags,
		Labels: make(map[string]string),
	})
}

// GetMetrics returns all metrics for a given name
func (mc *MetricsCollector) GetMetrics(name string) []Metric {
	mc.mu.RLock()
	defer mc.mu.RUnlock()

	if metrics, exists := mc.metrics[name]; exists {
		// Return a copy
		result := make([]Metric, len(metrics))
		copy(result, metrics)
		return result
	}
	return []Metric{}
}

// GetAggregate returns aggregated metrics
func (mc *MetricsCollector) GetAggregate(key string) interface{} {
	mc.mu.RLock()
	defer mc.mu.RUnlock()

	return mc.aggregates[key]
}

// GetAllMetrics returns all recorded metrics
func (mc *MetricsCollector) GetAllMetrics() map[string][]Metric {
	mc.mu.RLock()
	defer mc.mu.RUnlock()

	result := make(map[string][]Metric)
	for k, v := range mc.metrics {
		result[k] = append([]Metric{}, v...)
	}
	return result
}

// Summary provides a summary of metrics
type Summary struct {
	MetricsCount   int
	AggregatesCount int
	UpTime         time.Duration
	CollectionTime time.Duration
}

// GetSummary returns a summary of collection statistics
func (mc *MetricsCollector) GetSummary() Summary {
	mc.mu.RLock()
	defer mc.mu.RUnlock()

	metricsCount := 0
	for _, m := range mc.metrics {
		metricsCount += len(m)
	}

	return Summary{
		MetricsCount:    metricsCount,
		AggregatesCount: len(mc.aggregates),
		UpTime:          time.Since(mc.startTime),
		CollectionTime:  time.Now().Sub(mc.startTime),
	}
}

// Reset clears all metrics
func (mc *MetricsCollector) Reset() {
	mc.mu.Lock()
	defer mc.mu.Unlock()

	mc.metrics = make(map[string][]Metric)
	mc.aggregates = make(map[string]interface{})
	mc.startTime = time.Now()
}

// PrometheusFormat exports metrics in Prometheus format
func (mc *MetricsCollector) PrometheusFormat() string {
	mc.mu.RLock()
	defer mc.mu.RUnlock()

	var result string

	// Write metrics
	for name, metrics := range mc.metrics {
		if len(metrics) == 0 {
			continue
		}

		// Use the latest metric
		latest := metrics[len(metrics)-1]

		tags := ""
		if len(latest.Tags) > 0 {
			for k, v := range latest.Tags {
				tags += fmt.Sprintf(`%s="%s",`, k, v)
			}
			tags = tags[:len(tags)-1] // Remove trailing comma
			tags = "{" + tags + "}"
		}

		result += fmt.Sprintf("%s%s %v\n", name, tags, latest.Value)
	}

	return result
}
